import subprocess,sys,json,time,os,re,struct,hashlib
from pathlib import Path
OUT=Path(__file__).resolve().parent
ROOT=OUT.parents[2]
IOS='E262D4C1-99BE-496B-8567-0291C14E6533'
ADB='/Users/anderson/Library/Android/sdk/platform-tools/adb'
CLI='/Users/anderson/.npm/_npx/99336612077b7094/node_modules/xcodebuildmcp/build/cli.js'
NODE24='/Users/anderson/.nvm/versions/node/v24.14.1/bin/node'
def log(d):
 with (OUT/'native-runtime.jsonl').open('a') as f:f.write(json.dumps(d,ensure_ascii=False)+'\n')
def run(cmd,timeout=55,binary=False,allow=False):
 if '5FD8C926-BC5A-4E9E-B5BE-2E080B2ED2A3' in str(cmd) or ('simctl' in cmd and 'booted' in cmd):raise RuntimeError('forbidden target')
 try:r=subprocess.run(cmd,capture_output=True,stdin=subprocess.DEVNULL,timeout=timeout)
 except subprocess.TimeoutExpired as e:
  log({'at':time.time(),'cmd':cmd,'timeout':timeout,'stdout':str(e.stdout),'stderr':str(e.stderr)});raise
 d={'at':time.time(),'cmd':cmd,'exit':r.returncode,'stderr':r.stderr.decode(errors='replace')}
 d.update({'bytes':len(r.stdout)} if binary else {'stdout':r.stdout.decode(errors='replace')});log(d)
 if r.returncode and not allow:raise RuntimeError(json.dumps(d))
 return r.stdout if binary else d['stdout']
def ios(kind,args=None):
 return run([NODE24,CLI,'ui-automation',kind,'--json',json.dumps({'simulatorId':IOS,**(args or {})}),'--output','json'])
def android_serial():
 s=json.loads((OUT/'native-processes.json').read_text())['androidSerial']
 if not s:raise RuntimeError('no checked serial')
 if run([ADB,'-s',s,'emu','avd','name']).strip().splitlines()[0]!='radiant-entrada-api34':raise RuntimeError('wrong AVD')
 return s
def android(args,binary=False,allow=False):return run([ADB,'-s',android_serial()]+args,binary=binary,allow=allow)
def capture(platform,stem):
 if not stem.startswith('native-'):raise RuntimeError('outside own prefix')
 dst=OUT/stem
 if dst.with_suffix('.png').exists():raise RuntimeError('refuse overwrite')
 if platform=='ios':
  raw=ios('snapshot-ui');dst.with_suffix('.ui.json').write_text(raw)
  print(raw[:24000])
  run(['xcrun','simctl','io',IOS,'screenshot',str(dst.with_suffix('.png'))])
 else:
  raw=android(['exec-out','uiautomator','dump','/dev/tty'],allow=True);dst.with_suffix('.ui-raw.txt').write_text(raw)
  m=re.search(r'<\?xml.*?</hierarchy>',raw,re.S)
  if m:
   dst.with_suffix('.ui.xml').write_text(m.group(0))
   import xml.etree.ElementTree as ET
   print(json.dumps([{k:n.get(k) for k in ['text','content-desc','bounds','clickable','scrollable','checkable','checked','enabled']} for n in ET.fromstring(m.group(0)).iter('node') if n.get('text') or n.get('content-desc') or n.get('scrollable')=='true'],ensure_ascii=False))
  else:print('UI XML unavailable; raw preserved')
  dst.with_suffix('.png').write_bytes(android(['exec-out','screencap','-p'],binary=True))
 png=dst.with_suffix('.png').read_bytes()
 if not png.startswith(b'\x89PNG\r\n\x1a\n'):raise RuntimeError('invalid PNG')
 print(json.dumps({'png':str(dst.with_suffix('.png')),'dimensions':struct.unpack('>II',png[16:24]),'sha256':hashlib.sha256(png).hexdigest()}))
if __name__=='__main__':
 if sys.argv[1]=='ios':print(ios(sys.argv[2],json.loads(sys.argv[3]) if len(sys.argv)>3 else {}))
 elif sys.argv[1]=='capture':capture(sys.argv[2],sys.argv[3])
 elif sys.argv[1]=='android':print(android(sys.argv[2:]))
 elif sys.argv[1]=='run':print(run(sys.argv[2:]))

